// What an independent review of the second round of charts found, test by
// test: a moving average that was not sampled, error bars of shares, which
// pair of axes is the first one, a trend line that goes on very far, the day
// of the ticks of a date axis, where a value axis crosses, a title that is
// moved; and the rules the first tests did not pin down.
//
// Every chart is generated by code. Excel is not at hand: what follows its
// known behaviour without having been compared with it is marked UNSURE.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { MAX_DRAWN_ITEMS, MAX_DRAWN_POINTS, MAX_LAYOUT_WEIGHT, chartLayoutWeight, chartValues, layoutChart, type ChartItem, type ChartLayout, type ChartScale } from '../src/layout/chart';
import type { Chart, ChartData, ChartGroup, ChartKind, ChartSeries } from '../src/model/sheet/chart';
import { catAx, chartXml, fakeMeasure, group, numLit, readChart, ser, strLit, title, valAx, xySer } from './chart-fixtures';

type Of<K extends ChartItem['kind']> = Extract<ChartItem, { kind: K }>;

function model(xml: string): Chart {
  const chart = readChart(xml);
  assert.ok(chart, 'the chart is read');
  return chart as Chart;
}

const lay = (xml: string, width = 480, height = 320, date1904 = false): ChartLayout => {
  const chart = model(xml);
  return layoutChart(chart, chartValues(chart), width, height, fakeMeasure, { date1904 });
};
const items = <K extends ChartItem['kind']>(layout: ChartLayout, kind: K, role?: string): Of<K>[] => layout.items.filter((item) => item.kind === kind && (role === undefined || item.role === role)) as Of<K>[];
const texts = (layout: ChartLayout, role: string): string[] => items(layout, 'text', role).map((item) => item.text);
const near = (actual: number, expected: number, message: string, tolerance = 1e-6) => assert.ok(Math.abs(actual - expected) <= tolerance, `${message}: ${actual} is not ${expected}`);
const right = (layout: ChartLayout) => layout.plot.x + layout.plot.width;
const bottom = (layout: ChartLayout) => layout.plot.y + layout.plot.height;
const valueY = (layout: ChartLayout, value: number, scale = layout.scale as ChartScale): number => bottom(layout) - ((value - scale.min) / (scale.max - scale.min)) * layout.plot.height;
const axis = (name: string, id: number, cross: number, position: string, inner = '', scaling = '<c:orientation val="minMax"/>', deleted = 0) =>
  `<c:${name}><c:axId val="${id}"/><c:scaling>${scaling}</c:scaling><c:delete val="${deleted}"/><c:axPos val="${position}"/>${inner}<c:crossAx val="${cross}"/></c:${name}>`;
const FIXED = (max: number, min = 0) => valAx('<c:majorGridlines/>', `<c:orientation val="minMax"/><c:max val="${max}"/><c:min val="${min}"/>`);
const trendOf = (inner: string) => `<c:trendline>${inner}</c:trendline>`;
const err = (inner: string) => `<c:errBars>${inner}</c:errBars>`;

// ------------------------------------------------- B1. what a layout may weigh

/** A chart of `count` points in each of `many` series with everything a series can carry. */
function heavy(kind: ChartKind, count: number, many: number, trends: string[]): Chart {
  const index: number[] = [];
  for (let i = 0; i < count; i++) index.push(i);
  const data = (value: (i: number) => number): ChartData => ({ kind: 'num', cache: { index, values: index.map(value) }, count });
  const shared = data((i) => 50 + 40 * Math.sin(i / 1000) + (i % 7));
  const xy = kind === 'scatter' || kind === 'bubble';
  const series: ChartSeries[] = [];
  for (let s = 0; s < many; s++) {
    series.push({
      index: s,
      order: s,
      values: shared,
      categories: xy ? data((i) => 45000 + i) : undefined,
      bubbleSizes: kind === 'bubble' ? data((i) => (i % 13) + 1) : undefined,
      trendlines: trends.map((type) => ({ type: type as 'movingAvg', order: 6, period: 2, forward: 5, backward: 5 })),
      smooth: true,
      dataLabels: { showValue: true, showCategory: true, showSeries: true },
      errorBars: [
        { direction: 'y', type: 'both', valueType: 'stdDev', value: 2 },
        { direction: 'x', type: 'both', valueType: 'cust', plus: shared, minus: shared },
      ],
    });
  }
  const type: ChartGroup = { kind, grouping: 'standard', axisIds: [1, 2], series, radarStyle: 'marker', scatterStyle: 'smoothMarker', bubbleScale: 300, dropLines: {}, hiLowLines: {}, upDownBars: {}, markers: true };
  return {
    groups: [type],
    axes: [
      { id: 1, kind: xy ? 'val' : 'cat', position: 'b', tickLabels: 'nextTo' },
      { id: 2, kind: 'val', position: 'l', tickLabels: 'nextTo', majorGridlines: {}, minorGridlines: {} },
    ],
    plotVisOnly: true,
    blanks: 'gap',
    palette: ['#4472C4', '#ED7D31', '#A5A5A5', '#FFC000', '#5B9BD5', '#70AD47'],
    notes: [],
    legend: { position: 'r' },
  };
}

test('a moving average of very many points is sampled like its series: its line holds no more points than a frame can show', () => {
  const chart = heavy('line', 100000, 8, Array.from({ length: 8 }, () => 'movingAvg'));
  const layout = layoutChart(chart, chartValues(chart), 640, 400, fakeMeasure);
  const trends = items(layout, 'path', 'trend');
  assert.ok(trends.length >= 8, `${trends.length} pieces of trend lines are drawn`);
  for (const trend of trends) assert.ok(trend.points.length <= MAX_DRAWN_POINTS * 4, `a trend line of ${trend.points.length} numbers`);
  let numbers = 0;
  for (const trend of trends) numbers += trend.points.length;
  assert.ok(numbers <= MAX_DRAWN_ITEMS * 4, `${numbers} numbers for the trend lines of 800,000 points`);
  assert.ok(chartLayoutWeight(layout) <= MAX_LAYOUT_WEIGHT, `the layout weighs ${chartLayoutWeight(layout)}`);
});

test('a sampled moving average keeps its peaks and its place', () => {
  // 50,000 points of 10 with one run of 1,000 at 510: the average of two reaches 510 there, and nowhere else.
  const values = Array.from({ length: 50000 }, (_value, i) => (i >= 30000 && i < 31000 ? 510 : 10));
  const xml = chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit(values), props: trendOf('<c:trendlineType val="movingAvg"/><c:period val="2"/>') })) + catAx() + FIXED(600) });
  const layout = lay(xml, 640, 400);
  const trend = items(layout, 'path', 'trend');
  let high = Infinity;
  let highX = 0;
  let count = 0;
  for (const piece of trend) {
    for (let i = 0; i + 1 < piece.points.length; i += 2) {
      count++;
      if (piece.points[i + 1] < high) {
        high = piece.points[i + 1];
        highX = piece.points[i];
      }
    }
  }
  assert.ok(count > 100 && count <= MAX_DRAWN_POINTS * 2, `${count} points of 49,999`);
  near(high, valueY(layout, 510), 'the peak of the average is drawn at its height', 0.01);
  near((highX - layout.plot.x) / layout.plot.width, 30500 / 50000, 'where it lies along the categories', 0.02);
  // A short series is not touched: every point of its average is one of the line.
  const short = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([1, 4, 9, 16, 25]), props: trendOf('<c:trendlineType val="movingAvg"/><c:period val="2"/>') })) + catAx() + FIXED(30) }));
  assert.equal(items(short, 'path', 'trend')[0].points.length, 8);
});

test('whatever a chart holds, what its layout weighs stays below one bound', () => {
  const cases: [ChartKind, number, number, string[]][] = [
    ['line', 100000, 40, ['movingAvg', 'poly', 'linear']],
    ['bar', 100000, 40, ['movingAvg']],
    ['area', 100000, 8, ['movingAvg', 'exp']],
    ['scatter', 100000, 4, ['movingAvg', 'poly']],
    ['scatter', 100000, 40, ['movingAvg']],
    ['bubble', 100000, 4, ['movingAvg']],
    ['radar', 100000, 40, []],
    ['stock', 100000, 4, ['movingAvg']],
    ['line', 7000, 5, ['movingAvg']],
    ['scatter', 7000, 4, ['movingAvg']],
    ['bar', 600, 60, ['linear']],
    // Few enough points for every one of them to be drawn with all it carries: too much, until fewer are drawn.
    ['scatter', 7900, 5, []],
  ];
  for (const [kind, count, many, trends] of cases) {
    const chart = heavy(kind, count, many, trends);
    const values = chartValues(chart);
    for (const [width, height] of [[640, 400], [4000, 3000], [100000, 100000]] as [number, number][]) {
      const layout = layoutChart(chart, values, width, height, fakeMeasure);
      const weight = chartLayoutWeight(layout);
      assert.ok(weight <= MAX_LAYOUT_WEIGHT, `${kind}, ${many} series of ${count} points in ${width} x ${height}: the layout weighs ${weight}`);
      assert.ok(layout.items.length > 5, `${kind}: something is drawn`);
    }
  }
});

// ------------------------------------------ B2. error bars of shares of 100 %

test('error bars of a series that is a share of 100 % are shares too: an amount is taken of the sum of its category', () => {
  const cats = strLit(['a', 'b']);
  const chart = (grouping: string, bars: string, type = 'barChart') =>
    lay(
      chartXml({
        plot:
          group(type, (type === 'barChart' ? '<c:barDir val="col"/>' : '') + `<c:grouping val="${grouping}"/>`, ser(0, { cat: cats, val: numLit([50, 20]), props: err(bars) }) + ser(1, { cat: cats, val: numLit([50, 60]) })) +
          catAx() +
          valAx(),
      }),
    );
  const first = (layout: ChartLayout): number[] => {
    const points = items(layout, 'path', 'error')[0].points;
    return [Math.max(points[1], points[3]), Math.min(points[1], points[3]), Math.max(points[5], points[7]), Math.min(points[5], points[7])];
  };
  const fixed = '<c:errBarType val="both"/><c:errValType val="fixedVal"/><c:noEndCap val="1"/><c:val val="5"/>';
  for (const type of ['barChart', 'lineChart']) {
    const shares = chart('percentStacked', fixed, type);
    assert.deepEqual([shares.scale?.min, shares.scale?.max], [0, 1]);
    const [low0, high0, low1, high1] = first(shares);
    // UNSURE: 5 of a category that sums to 100 is 0.05 of the axis; of one that sums to 80 it is 0.0625.
    near(low0, valueY(shares, 0.45), `${type}: 50 less 5 of 100`);
    near(high0, valueY(shares, 0.55), `${type}: 50 and 5 of 100`);
    near(low1, valueY(shares, 0.25 - 0.0625), `${type}: 20 less 5 of 80`);
    near(high1, valueY(shares, 0.25 + 0.0625), `${type}: 20 and 5 of 80`);
    assert.ok(low0 - high0 < shares.plot.height / 5, `${type}: the bar does not span the axis`);
  }
  const percent = first(chart('percentStacked', '<c:errBarType val="both"/><c:errValType val="percentage"/><c:noEndCap val="1"/><c:val val="10"/>'));
  const scaled = chart('percentStacked', fixed);
  near(percent[1], valueY(scaled, 0.55), 'ten per cent of 50 of 100');
  near(percent[3], valueY(scaled, 0.25 + 0.025), 'ten per cent of 20 of 80');
  // 50 and 20: mean 35, deviation of the sample 21.2132...; around the mean of the series, as shares of each category.
  const deviation = first(chart('percentStacked', '<c:errBarType val="both"/><c:errValType val="stdDev"/><c:noEndCap val="1"/><c:val val="1"/>'));
  const sd = Math.sqrt(450);
  near(deviation[1], valueY(scaled, Math.min((35 + sd) / 100, 1)), 'the mean and a deviation, of 100');
  near(deviation[2], valueY(scaled, (35 - sd) / 80), 'the mean less a deviation, of 80');
  const error = first(chart('percentStacked', '<c:errBarType val="both"/><c:errValType val="stdErr"/><c:noEndCap val="1"/>'));
  near(error[1], valueY(scaled, 0.5 + sd / Math.sqrt(2) / 100), 'the standard error, of 100');
  // Stacked without shares, and side by side: amounts are amounts.
  const stacked = chart('stacked', fixed);
  near(first(stacked)[1], valueY(stacked, 55), 'stacked: 50 and 5');
  const plain = chart('clustered', fixed);
  near(first(plain)[0], valueY(plain, 45), 'side by side: 50 less 5');
});

// ----------------------------------------------- B3. which pair is the first

const CATS5 = strLit(['Oca', 'Şub', 'Mar', 'Nis', 'May']);
const barsOn = (ids: number[]) => `<c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>${ser(0, { cat: CATS5, val: numLit([10, 30, 20, 22, 25]) })}${ids.map((id) => `<c:axId val="${id}"/>`).join('')}</c:barChart>`;
const lineOn = (ids: number[]) => `<c:lineChart><c:grouping val="standard"/>${ser(1, { cat: CATS5, val: numLit([1200, 900, 1500, 100, 700]) })}${ids.map((id) => `<c:axId val="${id}"/>`).join('')}</c:lineChart>`;
const FIRST_PAIR = axis('catAx', 1, 2, 'b') + axis('valAx', 2, 1, 'l', '<c:majorGridlines/>');
const SECOND_PAIR = axis('valAx', 4, 3, 'r', '<c:crosses val="max"/>') + axis('catAx', 3, 4, 'b', '<c:crosses val="autoZero"/>', undefined, 1);

test('the first pair of axes is the one whose category axis is shown and whose value axis crosses at the start, whichever chart type the file writes first', () => {
  const usual = lay(chartXml({ plot: barsOn([1, 2]) + lineOn([3, 4]) + FIRST_PAIR + SECOND_PAIR }));
  // The line stands first in the file, and is drawn against the second pair.
  const turned = lay(chartXml({ plot: lineOn([3, 4]) + barsOn([1, 2]) + FIRST_PAIR + SECOND_PAIR }));
  for (const [name, layout] of [['bars first', usual], ['line first', turned]] as [string, ChartLayout][]) {
    assert.ok((layout.scale?.max as number) <= 40 && (layout.scale2?.max as number) >= 1500, `${name}: the scale of the columns is the first (${layout.scale?.max}, ${layout.scale2?.max})`);
    const categories = items(layout, 'text', 'category');
    assert.ok(categories.length === 5 && categories.every((item) => item.y > bottom(layout)), `${name}: the categories stand below`);
    const ticks = items(layout, 'text', 'tick');
    assert.ok(ticks.filter((item) => item.x < layout.plot.x).some((item) => item.text === '30') && ticks.filter((item) => item.x > right(layout)).some((item) => item.text === '1000'), `${name}: the columns are counted at the left, the line at the right`);
    assert.equal(items(layout, 'path', 'axis').length, 3, `${name}: a line for the categories and one for each scale; none for the category axis that is deleted`);
    assert.equal(items(layout, 'path', 'grid').length, (layout.scale as ChartScale).ticks.length, `${name}: the grid lines are those of the first value axis`);
  }
  assert.deepEqual(usual.plot, turned.plot, 'the plot area is the same either way');
  // The axes of the second pair listed first, and both chart types in either order.
  const listed = lay(chartXml({ plot: lineOn([3, 4]) + barsOn([1, 2]) + SECOND_PAIR + FIRST_PAIR }));
  assert.deepEqual([listed.scale?.max, listed.plot], [turned.scale?.max, turned.plot]);
});

test('two pairs that both could be the first: the one whose axes the file lists first (UNSURE)', () => {
  const pairA = axis('catAx', 1, 2, 'b') + axis('valAx', 2, 1, 'l');
  const pairB = axis('catAx', 3, 4, 'b') + axis('valAx', 4, 3, 'l');
  const a = lay(chartXml({ plot: lineOn([3, 4]) + barsOn([1, 2]) + pairA + pairB }));
  assert.ok((a.scale?.max as number) <= 40, 'the pair that is listed first, though its chart type comes second');
  const b = lay(chartXml({ plot: lineOn([3, 4]) + barsOn([1, 2]) + pairB + pairA }));
  assert.ok((b.scale?.max as number) >= 1500, 'and the other way round');
  // Neither says it is the second (both category axes deleted, both value axes at the end): again the first listed.
  const deleted = (cat: number, val: number) => axis('valAx', val, cat, 'r', '<c:crosses val="max"/>') + axis('catAx', cat, val, 'b', '', undefined, 1);
  const neither = lay(chartXml({ plot: lineOn([3, 4]) + barsOn([1, 2]) + deleted(1, 2) + deleted(3, 4) }));
  assert.ok((neither.scale?.max as number) <= 40, 'the first listed');
});

test('a second value axis that does not say where it stands: its line, too, is drawn on the other side', () => {
  const layout = lay(chartXml({ plot: barsOn([1, 2]) + lineOn([3, 4]) + FIRST_PAIR + axis('catAx', 3, 4, 'b', '', undefined, 1) + axis('valAx', 4, 3, 'l') }));
  const lines = items(layout, 'path', 'axis').filter((item) => item.points[0] === item.points[2]);
  assert.equal(lines.length, 2, 'two standing lines');
  assert.ok(lines.some((item) => Math.abs(item.points[0] - layout.plot.x) <= 0.5) && lines.some((item) => Math.abs(item.points[0] - right(layout)) <= 0.5), 'one at the left, one at the right');
});

// ------------------------------------------------ B4. a trend line that goes far

test('a trend line that goes on very far keeps its slope: it ends on the edge of the plot area at the value it has there', () => {
  const five = (forward: number) => ser(0, { cat: strLit(['a', 'b', 'c', 'd', 'e']), val: numLit([2, 4, 5, 4, 5]), props: trendOf(`<c:trendlineType val="linear"/><c:forward val="${forward}"/>`) });
  for (const forward of [2, 50000, 1e7, 1e300]) {
    const layout = lay(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', five(forward)) + catAx() + FIXED(10) }));
    const points = items(layout, 'path', 'trend')[0].points;
    const slot = layout.plot.width / 5;
    near(points[0], layout.plot.x + slot / 2, `forward ${forward}: from the first category`);
    near(points[1], valueY(layout, 2.8), `forward ${forward}: at 2.8`, 1e-4);
    near(points[points.length - 2], right(layout), `forward ${forward}: to the edge`, 1e-4);
    // Slope 0.6, intercept 2.2: at 5.5, where the categories end, the line is at 5.5.
    near(points[points.length - 1], valueY(layout, 5.5), `forward ${forward}: at the value the line has there`, 1e-4);
  }
  // A scatter series: y = x, far beyond an axis that ends at 10.
  for (const forward of [1000, 1e7]) {
    const xml = chartXml({
      plot:
        group('scatterChart', '<c:scatterStyle val="marker"/>', xySer(0, { cat: numLit([1, 2, 3, 4]), val: numLit([1, 2, 3, 4]), props: trendOf(`<c:trendlineType val="linear"/><c:forward val="${forward}"/><c:backward val="${forward}"/>`) })) +
        axis('valAx', 111, 222, 'b', '', '<c:max val="10"/><c:min val="0"/>') +
        axis('valAx', 222, 111, 'l', '', '<c:max val="10"/><c:min val="0"/>'),
    });
    const layout = lay(xml, 500, 500);
    const points = items(layout, 'path', 'trend')[0].points;
    near(points[0], layout.plot.x, `forward ${forward}: from the corner`, 1e-4);
    near(points[1], bottom(layout), `forward ${forward}: of the plot area`, 1e-4);
    near(points[points.length - 2], right(layout), `forward ${forward}: to the opposite corner`, 1e-4);
    near(points[points.length - 1], layout.plot.y, `forward ${forward}: y = x`, 1e-4);
  }
});

// ----------------------------------------------------------- B5. smaller ones

/** 2024-01-01 is serial 45292. */
const D = 45292;
const dateAxis = (inner = '', format = 'd.m.yyyy') => `<c:dateAx><c:axId val="111"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="b"/><c:numFmt formatCode="${format}" sourceLinked="0"/>${inner}<c:crossAx val="222"/></c:dateAx>`;
const dated = (serials: number[], inner: string, format: string) => chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { cat: numLit(serials), val: numLit(serials.map((_value, i) => i + 1)) }), '<c:marker val="1"/>') + dateAxis(inner, format) + valAx() });

test('ticks of a date axis a month apart keep the day of the first: the last day of a month that is shorter', () => {
  // From 31 January to 5 April 2024, counted in days, a tick every month.
  const layout = lay(dated([D + 30, D + 60, D + 95], '<c:baseTimeUnit val="days"/><c:majorUnit val="1"/><c:majorTimeUnit val="months"/>', 'd.m'), 900, 320);
  assert.deepEqual(texts(layout, 'category'), ['31.1', '29.2', '31.3'], '31 January, the last of February, 31 March again');
  // A year apart from 29 February: 28 February in a year that has no 29th, 29 February again in the next leap year.
  const years = lay(dated([D + 59, D + 59 + 366 * 4 + 5], '<c:baseTimeUnit val="days"/><c:majorUnit val="1"/><c:majorTimeUnit val="years"/>', 'd.m.yy'), 900, 320);
  assert.deepEqual(texts(years, 'category'), ['29.2.24', '28.2.25', '28.2.26', '28.2.27', '29.2.28']);
});

test('ticks of a date axis go on over the end of a year', () => {
  // 15 November 2024 is 319 days after 1 January.
  const layout = lay(dated([D + 319, D + 366 + 40], '<c:baseTimeUnit val="months"/><c:majorUnit val="1"/><c:majorTimeUnit val="months"/>', 'mmm yy'), 900, 320);
  assert.deepEqual(texts(layout, 'category'), ['Nov 24', 'Dec 24', 'Jan 25', 'Feb 25']);
});

test('a date axis counts in the calendar of the workbook: serial numbers from 1904 lie in other months and years', () => {
  // 1, 60 and 100: in the calendar of 1900 January, February (the 29th that never was) and April; from 1904 January, March and April.
  const months = (date1904: boolean) => items(lay(dated([1, 60, 100], '<c:baseTimeUnit val="months"/>', 'mmm'), 480, 320, date1904), 'path', 'line')[0].points;
  const width = (date1904: boolean) => lay(dated([1, 60, 100], '<c:baseTimeUnit val="months"/>', 'mmm'), 480, 320, date1904).plot;
  near(months(false)[2], width(false).x + (1.5 / 4) * width(false).width, 'from 1900: the second point in the second month');
  near(months(true)[2], width(true).x + (2.5 / 4) * width(true).width, 'from 1904: in the third');
  // 1, 366 and 800: 1900 has 366 days in this calendar, so 366 is still 1900; from 1904 it is the first day of 1905.
  const years = (date1904: boolean) => items(lay(dated([1, 366, 800], '<c:baseTimeUnit val="years"/>', 'yyyy'), 480, 320, date1904), 'path', 'line')[0].points;
  near(years(false)[2], years(false)[0], 'from 1900: the second point in the year of the first');
  assert.ok(years(true)[2] > years(true)[0] + 50, 'from 1904: a year on');
  assert.deepEqual(texts(lay(dated([1, 366, 800], '<c:baseTimeUnit val="years"/>', 'yyyy'), 480, 320, true), 'category'), ['1904', '1905', '1906']);
});

test('a value axis that crosses at a category: beyond the last one it stands at the far side; between the categories it stays at the start', () => {
  const at = (crossesAt: number) => lay(chartXml({ plot: barsOn([1, 2]) + axis('catAx', 1, 2, 'b') + axis('valAx', 2, 1, 'l', `<c:crossesAt val="${crossesAt}"/>`) }));
  const side = (layout: ChartLayout) => (items(layout, 'text', 'tick').every((item) => item.x > right(layout)) ? 'right' : items(layout, 'text', 'tick').every((item) => item.x < layout.plot.x) ? 'left' : 'both');
  assert.equal(side(at(6)), 'right', 'beyond the five categories: at the far side');
  assert.equal(side(at(5)), 'left', 'UNSURE: at the last category the axis would stand inside the plot area, which is not drawn: it stays at the start');
  assert.equal(side(at(3)), 'left', 'between the categories: at the start');
  assert.equal(side(at(1)), 'left');
  const noted = model(chartXml({ plot: barsOn([1, 2]) + axis('catAx', 1, 2, 'b') + axis('valAx', 2, 1, 'l', '<c:crossesAt val="3"/>') })).notes;
  assert.ok(noted.some((note) => /crosses .* at a stated place/.test(note)), 'which is said in the notes of the chart');
});

test('a title that is moved stays in the frame, whole', () => {
  const moved = (x: number, y: number) =>
    lay(
      chartXml({ head: title('Uzun bir grafik başlığı').replace('<c:overlay', `<c:layout><c:manualLayout><c:xMode val="factor"/><c:yMode val="factor"/><c:x val="${x}"/><c:y val="${y}"/></c:manualLayout></c:layout><c:overlay`), plot: barsOn([1, 2]) + FIRST_PAIR }),
      500,
      400,
    );
  for (const [x, y] of [[1, 1], [-1, -1], [0.9, 0], [-0.9, 0.99]]) {
    const item = items(moved(x, y), 'text', 'title')[0];
    const half = fakeMeasure(item.text, item.font) / 2;
    assert.equal(item.text, 'Uzun bir grafik başlığı');
    assert.ok(item.x - half >= -1e-6 && item.x + half <= 500 + 1e-6, `moved by ${x}: the title lies between the sides of the frame (${item.x - half}..${item.x + half})`);
    assert.ok(item.y - item.font.size >= -1e-6 && item.y <= 400 + 1e-6, `moved by ${y}: and between its top and bottom (${item.y})`);
  }
  const little = items(moved(0.1, 0.25), 'text', 'title')[0];
  assert.deepEqual([little.x, little.align], [300, 'center'], 'a title that fits where it is moved to is not touched');
});

