test('high-low lines need two series; a bubble of a negative size is in no item unless the chart shows such', () => {
  const one = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([1, 2, 3]) }), '<c:hiLowLines/>') + catAx() + valAx() }));
  assert.equal(items(one, 'path', 'hilow').length, 0, 'one series has no highest and lowest');
  const bubbles = (tail: string) =>
    lay(
      chartXml({
        plot:
          group('bubbleChart', '<c:varyColors val="0"/>', `<c:ser><c:idx val="0"/><c:order val="0"/><c:xVal>${numLit([1, 2, 3])}</c:xVal><c:yVal>${numLit([1, 2, 3])}</c:yVal><c:bubbleSize>${numLit([4, -9, 1])}</c:bubbleSize></c:ser>`, tail) +
          axis('valAx', 111, 222, 'b') +
          axis('valAx', 222, 111, 'l'),
      }),
    );
  const count = (layout: ChartLayout) => items(layout, 'circles').reduce((sum, item) => sum + item.points.length / 3, 0);
  assert.equal(count(bubbles('')), 2, 'two bubbles in all');
  assert.equal(count(bubbles('<c:showNegBubbles val="0"/>')), 2);
  assert.equal(count(bubbles('<c:showNegBubbles val="1"/>')), 3);
});

test('minor grid lines of a logarithmic axis lie at the multiples of its powers', () => {
  const layout = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([1, 10, 100]) })) + catAx() + valAx('<c:majorGridlines/><c:minorGridlines/>', '<c:logBase val="10"/><c:orientation val="minMax"/>') }));
  const grid = items(layout, 'path', 'grid');
  // Minor lines first: 2..9 and 20..90; then the three powers.
  assert.equal(grid.length, 16 + 3);
  const share = (y: number) => (bottom(layout) - y) / layout.plot.height;
  near(share(grid[0].points[1]), Math.log10(2) / 2, 'the first minor line at 2', 0.01);
  near(share(grid[7].points[1]), Math.log10(9) / 2, 'the eighth at 9', 0.01);
  near(share(grid[8].points[1]), Math.log10(20) / 2, 'the ninth at 20', 0.01);
});

test('error bars along x have caps that stand; drop lines end where the series stand; an amount of its own counts without its sign', () => {
  const scatter = lay(
    chartXml({
      plot:
        group('scatterChart', '<c:scatterStyle val="marker"/>', xySer(0, { cat: numLit([10, 20, 30]), val: numLit([1, 2, 3]), props: err('<c:errDir val="x"/><c:errBarType val="both"/><c:errValType val="fixedVal"/><c:val val="5"/>') })) +
        axis('valAx', 111, 222, 'b', '', '<c:max val="40"/><c:min val="0"/>') +
        axis('valAx', 222, 111, 'l', '', '<c:max val="4"/><c:min val="0"/>'),
    }),
  );
  const points = items(scatter, 'path', 'error')[0].points;
  assert.equal(points.length, 3 * 12, 'a line and two caps for each point');
  const y = valueY(scatter, 1);
  assert.deepEqual([points[1], points[3]], [y, y], 'the bar lies');
  near(points[4], points[0], 'the first cap at the start of the bar');
  near(points[6], points[0], 'and stands');
  near(points[5], y - 4, 'from four pixels above');
  near(points[7], y + 4, 'to four below');
  near(points[8], points[2], 'the second cap at its end');
  const one = (type: string) => items(lay(chartXml({ plot: group('scatterChart', '<c:scatterStyle val="marker"/>', xySer(0, { cat: numLit([10]), val: numLit([1]), props: err(`<c:errDir val="x"/><c:errBarType val="${type}"/><c:errValType val="fixedVal"/><c:val val="5"/>`) })) + axis('valAx', 111, 222, 'b', '', '<c:max val="40"/><c:min val="0"/>') + axis('valAx', 222, 111, 'l', '', '<c:max val="4"/><c:min val="0"/>') })), 'path', 'error')[0].points;
  assert.equal(one('plus').length, 8, 'a bar to one side has one cap');
  near(one('plus')[4], one('plus')[2], 'at the end it reaches out to');
  near(one('minus')[4], one('minus')[0], 'or at the other');

  // Drop lines end on the category axis, wherever that crosses: here at the top of the scale.
  const dropped = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([10, 30, 20]) }), '<c:dropLines/>') + catAx('<c:crosses val="max"/>') + FIXED(40) }));
  const drop = items(dropped, 'path', 'drop')[0].points;
  near(drop[1], valueY(dropped, 10), 'from the point');
  near(drop[3], dropped.plot.y, 'up to the axis at the top');
  const floor = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([10, 30, 20]) }), '<c:dropLines/>') + catAx('<c:crossesAt val="20"/>') + FIXED(40) }));
  near(items(floor, 'path', 'drop')[0].points[3], valueY(floor, 20), 'or to the value the axis crosses at');

  const own = lay(chartXml({ plot: group('lineChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([10, 20, 30]), props: err(`<c:errBarType val="both"/><c:errValType val="cust"/><c:noEndCap val="1"/><c:plus>${numLit([-4, 4, 4])}</c:plus><c:minus>${numLit([-2, 2, 2])}</c:minus>`) })) + catAx() + FIXED(40) }));
  const bar = items(own, 'path', 'error')[0].points;
  near(Math.min(bar[1], bar[3]), valueY(own, 14), 'an amount of -4 reaches up by 4');
  near(Math.max(bar[1], bar[3]), valueY(own, 8), 'an amount of -2 reaches down by 2');
});

test('a pie with a second plot split by per cent takes shares, not values', () => {
  const layout = lay(chartXml({ plot: group('ofPieChart', '<c:ofPieType val="pie"/><c:varyColors val="1"/>', ser(0, { val: numLit([100, 200, 300, 400]) }), '<c:splitType val="percent"/><c:splitPos val="25"/>', false) }));
  const shares = items(layout, 'slice').map((slice) => Math.round(((slice.end - slice.start) / (Math.PI * 2)) * 1000) / 1000);
  assert.deepEqual(shares, [0.3, 0.4, 0.3], 'the points below a quarter of the whole together, whatever their values');
});
